import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../api/axios';
import { Lock, Mail, ShieldAlert, LogIn } from 'lucide-react';

export default function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Direct Gmail Authentication Handler
  const handleGmailSignIn = async (e) => {
    e.preventDefault();
    if (!email) {
      setError('Apnar Gmail address-ti likhun!');
      return;
    }

    try {
      setLoading(true);
      setError('');
      const res = await API.post('/auth/google-login', {
        email: email,
        name: email.split('@')[0]
      });

      if (res.data.token) {
        localStorage.setItem('admin_token', res.data.token);
        localStorage.setItem('admin_user', JSON.stringify(res.data.user));
        navigate('/');
      }
    } catch (err) {
      setError(err.response?.data?.error || 'Login fail hoyeche! Access denied.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4 font-sans">
      <div className="bg-white rounded-3xl p-8 max-w-md w-full shadow-2xl space-y-6">
        <div className="text-center space-y-1">
          <div className="w-14 h-14 bg-emerald-100 text-emerald-700 rounded-2xl flex items-center justify-center mx-auto mb-3 font-black text-xl shadow-inner">
            CF
          </div>
          <h2 className="text-2xl font-black text-gray-900">CityFood Admin</h2>
          <p className="text-xs text-gray-500 font-semibold">Gmail diye panel-e login korun</p>
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 text-red-700 text-xs rounded-xl flex items-center gap-2 font-bold">
            <ShieldAlert className="w-4 h-4 text-red-600 flex-shrink-0" />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleGmailSignIn} className="space-y-4 text-xs font-semibold">
          <div>
            <label className="block mb-1 text-gray-700 font-bold">Authorized Admin Gmail</label>
            <div className="relative">
              <Mail className="w-4 h-4 text-gray-400 absolute left-3 top-3" />
              <input
                type="email"
                required
                placeholder="yourname@gmail.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full pl-9 pr-3.5 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none text-sm"
              />
            </div>
            <p className="text-[10px] text-gray-400 mt-1">First-time login korle super admin hishebe save hobe.</p>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold text-sm shadow-md shadow-emerald-600/20 transition-all flex items-center justify-center gap-2 cursor-pointer active:scale-95"
          >
            <LogIn className="w-4 h-4" />
            {loading ? 'Verifying Gmail...' : 'Login with Gmail'}
          </button>
        </form>
      </div>
    </div>
  );
}
